import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.List;

public class DocumentTest {

    @Test
    public void documentCreationShell() {
        Document document = Document.createShell("https://www.example.com");
        assertNotNull(document);
    }

    @Test
    public void documentLocation() {
        Document document = Document.createShell("https://www.example.com");
        assertEquals("https://www.example.com", document.location());
    }

    @Test
    public void documentConnection() {
        Connection connection = new Connection();
        Document document = Document.createShell(connection);
        assertNotNull(document.connection());
    }

    @Test
    public void documentHead() {
        Document document = Document.createShell("https://www.example.com");
        assertEquals(null, document.head());
    }

    @Test
    public void documentBody() {
        Document document = Document.createShell("https://www.example.com");
        assertEquals(null, document.body());
    }

    @Test
    public void documentForms() {
        Document document = Document.createShell("https://www.example.com");
        assertTrue(document.forms().isEmpty());
    }

    @Test
    public void documentExpectForm() {
        Document document = Document.createShell("https://www.example.com");
        FormElement form = new FormElement();
        assertEquals(form, document.expectForm(".form"));
    }

    @Test
    public void documentTitle() {
        Document document = Document.createShell("https://www.example.com");
        assertEquals(null, document.title());
    }

    @Test
    public void documentsetTitle() {
        Document document = Document.createShell("https://www.example.com");
        String title = "Test Title";
        document.setTitle(title);
        assertEquals(title, document.title());
    }

    @Test
    public void createElement() {
        Document document = Document.createShell("https://www.example.com");
        Element element = new Tag();
        assertEquals(element, document.createElement("div"));
    }

    @Test
    public void outerHtml() {
        String html = "<html><body>Hello World!</body></html>";
        Document document = Jsoup.parse(html);
        assertEquals(html, document.outerHtml());
    }

    @Test
    public void text() {
        Document document = Jsoup.parse("<p>Hello World!</p>");
        Element element = new Tag();
        String text = "Hello World!";
        assertEquals(text, document.text(element));
    }

    @Test
    public void nodeName() {
        Document document = Jsoup.parse("<html><body></body></html>");
        assertEquals("HTML", document.nodeName());
    }

    @Test
    public void charset() {
        Charset charset = Charset.forName("UTF-8");
        Document document = Jsoup.parse("<html><body>Hello World!</body></html>", "utf-8");
        assertEquals(charset, document.charset());
    }

    @Test
    public void updateMetaCharsetElement() {
        Document document = Jsoup.parse("<meta charset=\"UTF-8\"></meta>");
        boolean update = true;
        document.updateMetaCharsetElement(update);
        assertTrue(update);
    }

    @Test
    public void outputSettings() {
        OutputSettings settings = new OutputSettings();
        Document document = Document.createShell("https://www.example.com");
        assertEquals(settings, document.outputSettings());
    }

    @Test
    public void shallowClone() {
        Document document = Jsoup.parse("<html><body>Hello World!</body></html>");
        Document clone = document.shallowClone();
        assertNotNull(clone);
        assertTrue(clone.outerHtml().equals(document.outerHtml()));
    }
